// Validator.java
public class Validator {
    public static int periksaUmur(int umur) throws UmurTidakValidException {
        if (umur < 0 || umur > 130) {
            throw new UmurTidakValidException("Umur tidak valid: " + umur);
        }
        return umur;
    }
}

