// Parser.java
public class Parser {
    public static int pemanggilan = 0;

    public static int keAngka(String teks, int bawaan) {
        try {
            return Integer.parseInt(teks.trim());
        } catch (NumberFormatException e) {
            return bawaan;
        } finally {
            pemanggilan++;
        }
    }

    public static int jumlahkan(String[] data) {
        int jumlah = 0;
        for (String d : data) {
            jumlah += keAngka(d, 0);
        }
        return jumlah;
    }
}

